mapper.select:
select ca.id as id, ca.identifier as username, ca.credential as password , ca.identity_type, ca.non_expired, ca.non_locked, ca.enabled, ca.app_id, ca.admin, u.user_id, ca.expire_date, ca.start_expire_date,
from ( select u.id as user_id,
from sys_users u where
) u left join ( select id, user_id,identity_type,identifier,credential,enabled,non_locked,admin, create_time,update_time,operator,app_id,if(expire_date < CURDATE() ,0,1) non_expired, expire_date, start_expire_date from sys_credentials where identity_type =#{identityType} and app_id =#{appId} and identifier = #{identifier} )ca on u.user_id = ca.user_id

select ca.id as id, ca.identifier as username, ca.credential as password , ca.identity_type, ca.non_expired, ca.non_locked, ca.enabled, ca.app_id, ca.admin, u.user_id, ca.expire_date, ca.start_expire_date,
from ( select u.id as user_id,
from sys_users u where username = #{userId} ) u left join ( select id, user_id,identity_type,identifier,credential,enabled,non_locked,admin, create_time,update_time,operator,app_id,if(expire_date < CURDATE() ,0,1) non_expired, expire_date, start_expire_date from sys_credentials where app_id =#{appId} and identifier = #{userId} order by create_time limit 1 )ca on u.user_id = ca.user_id

select u.id as user_id, if(expire_date < CURDATE() ,0,1) non_expired, u.expire_date, u.start_expire_date, u.enabled, u.non_locked,
from sys_users u
and id = #{userId}
and client_id = #{clientId}

select t.* from ( with login_log as ( select max(login_time) as lastLoginTime,user_id,credential_id,app_id,login_type from sys_login_histroy
and app_id = #{userModel.appId}
group by user_id, credential_id, app_id, login_type), login_count as ( select count(login_time) as loginCounts,user_id,credential_id,app_id,login_type from sys_login_histroy
and app_id = #{userModel.appId}
and login_time >= #{userModel.startTime}
and login_time <= #{userModel.endTime}
group by user_id, credential_id, app_id, login_type ), user_data as ( select u.id as user_id, u.expire_date, u.start_expire_date, u.enabled, u.non_locked, u.username, u.email, u.firstname, u.lastname, u.phone, u.operator, u.create_time, u.update_time, u.labelstud_token, u.client_id, u.employee_id, u.remark, c.id as cid, c.user_id as cuid, c.app_id as cai, c.identity_type as cit, c.identifier as ci, c.credential as cc, c.enabled as ce, c.non_locked as cnl, c.create_time as ct, c.update_time as cut, c.expire_Date as ced, c.start_expire_date as csed, c.operator as co, c.admin as ca, case when u.expire_date < CURDATE() then 0 else 1 end as non_expired from sys_users as u left join sys_credentials as c on c.user_id = u.id
and c.app_id = #{userModel.appId}
and u.username = #{userModel.userId}
and u.client_id = #{userModel.clientId}
and c.admin = #{userModel.admin}
and u.enabled = #{userModel.status}
and (u.username like concat('%',#{userModel.username},'%') or u.firstname like concat('%',#{userModel.username},'%'))
and u.client_id in
#{clientId}
and (u.id in
#{userId}
or u.username in
#{username}
)
) select f1.*, lastLoginTime as lastLoginTime, ifnull(loginCounts, 0) as loginCounts, if(loginCounts is not null, 100, 0) as loginCompleteRate -- 完成率 from user_data as f1 left join login_log as f2 on f1.user_id = f2.user_id and f1.user_id = f2.user_id and f1.cid = f2.credential_id and f1.cai = f2.app_id and f1.cit = f2.login_type left join login_count as f3 on f1.user_id = f3.user_id and f1.user_id = f3.user_id and f1.cid = f3.credential_id and f1.cai = f3.app_id and f1.cit = f3.login_type ) t where 1=1
and t.loginCompleteRate = #{userModel.loginCompleteRate}

with login_log as ( select user_id, count(l.login_time) as loginCounts, credential_id, app_id, login_type from sys_login_histroy as l
and l.app_id = #{userModel.appId}
group by user_id,credential_id,app_id,login_type ), user_data as ( select u.id as user_id, u.expire_date,u.start_expire_date,u.enabled,u.non_locked,u.username, u.email,u.firstname,u.lastname,u.phone, u.operator, u.create_time, u.update_time, u.labelstud_token, u.client_id,u.employee_id, u.remark, c.id as cid,c.user_id as cuid,c.app_id as cai,c.identity_type as cit,c.identifier as ci, c.credential as cc, c.enabled as ce,c.non_locked as cnl,c.create_time as ct, c.update_time as cut,c.expire_Date as ced, c.start_expire_date as csed,c.operator as co, c.admin as ca, case when u.expire_date < CURDATE() then 0 else 1 end as non_expired from sys_users as u left join sys_credentials as c on c.user_id = u.id
and c.app_id = #{userModel.appId}
and u.username = #{userModel.userId}
and u.client_id = #{userModel.clientId}
and c.admin = #{userModel.admin}
and u.enabled = #{userModel.status}
and (u.username like concat('%',#{userModel.username},'%') or u.firstname like concat('%',#{userModel.username},'%'))
and u.client_id in
#{clientId}
and (u.id in
#{userId}
or u.username in
#{username}
)
) select f1.*, ifnull(loginCounts, 0) as loginCounts, if(loginCounts is not null, 100, 0) as loginCompleteRate -- 完成率 from user_data as f1 left join login_log as f2 on f1.user_id = f2.user_id and f1.user_id = f2.user_id and f1.cid = f2.credential_id and f1.cai = f2.app_id and f1.cit = f2.login_type

select count(1) from ( with login_log as ( select max(login_time) as lastLoginTime,user_id,credential_id,app_id,login_type from sys_login_histroy
and app_id = #{userModel.appId}
group by user_id, credential_id, app_id, login_type), login_count as ( select count(login_time) as loginCounts,user_id,credential_id,app_id,login_type from sys_login_histroy
and app_id = #{userModel.appId}
and login_time >= #{userModel.startTime}
and login_time <= #{userModel.endTime}
group by user_id, credential_id, app_id, login_type ), user_data as ( select u.id as user_id, u.expire_date, u.start_expire_date, u.enabled, u.non_locked, u.username, u.email, u.firstname, u.lastname, u.phone, u.operator, u.create_time, u.update_time, u.labelstud_token, u.client_id, u.employee_id, u.remark, c.id as cid, c.user_id as cuid, c.app_id as cai, c.identity_type as cit, c.identifier as ci, c.credential as cc, c.enabled as ce, c.non_locked as cnl, c.create_time as ct, c.update_time as cut, c.expire_Date as ced, c.start_expire_date as csed, c.operator as co, c.admin as ca, case when u.expire_date < CURDATE() then 0 else 1 end as non_expired from sys_users as u left join sys_credentials as c on c.user_id = u.id
and c.app_id = #{userModel.appId}
and u.username = #{userModel.userId}
and u.client_id = #{userModel.clientId}
and c.admin = #{userModel.admin}
and u.enabled = #{userModel.status}
and (u.username like concat('%',#{userModel.username},'%') or u.firstname like concat('%',#{userModel.username},'%'))
and u.client_id in
#{clientId}
and (u.id in
#{userId}
or u.username in
#{username}
)
) select f1.*, lastLoginTime as lastLoginTime, ifnull(loginCounts, 0) as loginCounts, if(loginCounts is not null, 100, 0) as loginCompleteRate -- 完成率 from user_data as f1 left join login_log as f2 on f1.user_id = f2.user_id and f1.user_id = f2.user_id and f1.cid = f2.credential_id and f1.cai = f2.app_id and f1.cit = f2.login_type left join login_count as f3 on f1.user_id = f3.user_id and f1.user_id = f3.user_id and f1.cid = f3.credential_id and f1.cai = f3.app_id and f1.cit = f3.login_type ) t where 1=1
and t.loginCompleteRate = #{userModel.loginCompleteRate}
